import { SyntheticTagWithSourceDtoSource } from './synthetic-tag-with-source-dto-source';
/**
 * The tag with source of a monitored entity.
 */
export interface SyntheticTagWithSourceDto {
    /**
     * The origin of the tag, such as AWS or Cloud Foundry.
     *
     * Custom tags use the `CONTEXTLESS` value.
     */
    context?: string;
    /**
     * The key of the tag.
     */
    key: string;
    source?: SyntheticTagWithSourceDtoSource;
    /**
     * The value of the tag.
     */
    value?: string;
}
